import sys, os, json
if not os.path.exists('deployed.json'):
    sys.exit(1)
try:
    data = json.load(open('deployed.json'))
    if data.get('deployed') is True and data.get('service') == 'orders-pipeline':
        with open('verified.json', 'w') as f:
            json.dump({'passed': True, 'artifact': 'deployed.json'}, f)
        sys.exit(0)
except Exception:
    pass
sys.exit(1)

